#!/usr/bin/env node
// E09 growth census setup: authority check, frozen-input pins, and a fully
// reproducible counted copy of the accepted R12 stage-one image.
// Diagnostic only. This script NEVER imports or executes the compiler image.
import {createHash} from 'node:crypto';
import {execFileSync} from 'node:child_process';
import {existsSync,mkdirSync,readFileSync,writeFileSync,realpathSync,statSync} from 'node:fs';
import {dirname,resolve} from 'node:path';
import {fileURLToPath} from 'node:url';

const DIR=dirname(fileURLToPath(import.meta.url));
const REPO='/Users/ilyagulya/Projects/My/bend';
const REQUEST=resolve(REPO,'checkpoints/local2039g32c-full/throughput/control-js.request.json');
const REQUEST_SHA='7141d8d73f9470013cd2b42be7613e7c96b496e5cf4c0329e4ba58759e738ffb';
const ORIGINAL_IMAGE=resolve(REPO,'checkpoints/local2039g24r12/bootstrap.json.cases/stage-one.js');
const ORIGINAL_SHA='85aff9e534c18b4a1d6acac5f3237571dabc58f2c1a75a7ea2040f1c477ab60e';
const EXPECTED_OUTPUT_SHA='c33227e028d767df9a9fff75663e42eb7374919dcf8e7dff14936a98d20008fb';
const FROZEN_ROOT='/private/tmp/bend2039g22-tiny-inline/checkpoints/.bootstrap_compiler_root_remote2039g21.bend';
const FROZEN_ROOT_SHA='402011f5a68aec3db82cc766e3cc21c61ca40d4b475031e0f915d93e0ead11ed';
const REPO_CHECKER_ARENA=resolve(REPO,'bend2/selfhost/checker_arena.bend');
const REPO_CHECKER_ARENA_SHA='d74873488827c5a8568b1238f05356ef43ec7c8a285ca0e25ab7b052f070ebdf';
const FROZEN_CHECKER_ARENA='/private/tmp/bend2039g22-tiny-inline/bend2/selfhost/checker_arena.bend';
const AUTHORITY_COMMIT='852b4387';
const NODE='/Users/ilyagulya/bend-g12-borrow-7782b78a-1e88-4ffd-9889-14cb52c6a5b9/.tools/node';
const BUN='/Users/ilyagulya/bend-g12-borrow-7782b78a-1e88-4ffd-9889-14cb52c6a5b9/.tools/bun';
const HEAVY_GATE=resolve(REPO,'evals/heavy_gate.ts');
const STEP_RUNTIME=resolve(REPO,'evals/checker_core_step_runtime.mjs');
const NATIVE_SEED=resolve(REPO,'evals/native_seed_runtime.mjs');
const CENSUS=resolve(DIR,'census.mjs');
const SETUP=resolve(DIR,'setup.mjs');

const IMAGE_NAME='r12-stage-one';
const ORIGINAL_COPY=resolve(DIR,IMAGE_NAME+'.original.mjs');
const COUNTED_COPY=resolve(DIR,IMAGE_NAME+'.counted.mjs');
const TRANSFORM=resolve(DIR,IMAGE_NAME+'.transform.json');
const PINS=resolve(DIR,'census-pins.json');
const AUTHORITY_DIR=resolve(DIR,'source-authority');
const AUTHORITY_FILE=resolve(AUTHORITY_DIR,'checker_arena.d7487348.bend');

const sha=bytes=>createHash('sha256').update(bytes).digest('hex');
const hashPath=path=>sha(readFileSync(path));
const fail=message=>{throw Error(message);};
const requireHash=(path,expected)=>{const actual=hashPath(path);if(actual!==expected)fail('Hash drift: '+path+'\n expected '+expected+'\n actual   '+actual);return actual;};

// Canonical order is fixed: it is the index space of the inserted counters.
const POOLS=[
 {pool:'node',type:'NodePool'},
 {pool:'pattern',type:'PatternPool'},
 {pool:'binder',type:'BinderPool'},
 {pool:'word',type:'WordPool'},
 {pool:'natural',type:'NaturalPool'},
 {pool:'name',type:'NamePool'},
];

const PRELUDE='const $g34 = globalThis.__g34 ??= {norm:new Float64Array(6),grow:new Float64Array(6),bad:new Float64Array(6),meta:new Float64Array(6),metaFull:new Float64Array(6),metaBad:0};\n';

function writeOnce(path,bytes){
 if(existsSync(path)){
  const existing=readFileSync(path);
  if(existing.equals(bytes))return 'reused';
  fail('Refusing to overwrite a different existing artifact: '+path);
 }
 writeFileSync(path,bytes,{flag:'wx'});
 return 'created';
}

function declarationLines(source){
 const lines=[];
 let offset=0;
 for(const line of source.split('\n')){
  if(line.startsWith('$D["'))lines.push({line,offset});
  offset+=line.length+1;
 }
 return lines;
}

function deriveRoomSelect(source,line,offset,entry){
 const keyPrefix='$D["';
 if(!line.startsWith(keyPrefix))fail('Not a declaration line for '+entry.pool);
 const keyEnd=line.indexOf('"]=',keyPrefix.length);
 if(keyEnd<0)fail('Malformed $D declaration: '+entry.pool);
 const key=line.slice(keyPrefix.length,keyEnd);
 const suffix='checker_arena.'+entry.pool+'_pool.room_select';
 if(!key.endsWith(suffix))fail('Unexpected declaration key for '+entry.pool+': '+key);
 if(line.slice(keyEnd+3,keyEnd+3+8)!=='run_clo(')fail('room_select '+entry.pool+' is not a curried declaration');
 const chain=/\$td<64\?(\$b\d+)\(\$v0,\$v1,\$v2,\$v3,\$v4,\$td\+1\):run_named5\((\$b\d+),\$v0,\$v1,\$v2,\$v3,\$v4,\$td\)/.exec(line);
 if(!chain)fail('room_select '+entry.pool+' declaration does not expose the expected 5-argument call site');
 if(chain[1]!==chain[2])fail('room_select '+entry.pool+' call-site function mismatch: '+chain[1]+' vs '+chain[2]);
 const fn=chain[1];
 const signature='function '+fn+'($v0,$v1,$v2,$v3,$v4,$td=0){';
 const first=source.indexOf(signature);
 if(first<0)fail('Missing emitted room_select body '+fn+' for '+entry.pool);
 if(source.indexOf(signature,first+1)>=0)fail('Duplicate emitted signature '+signature);
 const offsetInsert=first+signature.length;
 const bodyEnd=source.indexOf('\nfunction ',first+1);
 const body=source.slice(offsetInsert,bodyEnd<0?source.length:bodyEnd);
 for(const marker of ['$p_is_false($v4)','$p_is_true($v4)','checker_arena.'+entry.type]){
  if(!body.includes(marker))fail('room_select '+entry.pool+' body lacks '+marker);
 }
 for(const marker of ['$p_array_new(','$p_u32_to_nat($v2)','$p_nat_add($v3,1)']){
  if(!body.includes(marker))fail('room_select '+entry.pool+' body lacks '+marker);
 }
 return {canonical:'checker_arena.'+entry.pool+'_pool.room_select',declarationKey:key,emittedFunction:fn,insertionOffset:offsetInsert,bodyBytes:body.length};
}

function deriveMetadataWrite(source){
 const suffix='checker_arena.metadata_write';
 const lines=declarationLines(source).filter(row=>{
  const keyEnd=row.line.indexOf('"]=',5);
  return keyEnd>0&&row.line.slice(5,keyEnd).endsWith(suffix);
 });
 if(lines.length!==1)fail('Expected exactly one metadata_write $D declaration, found '+lines.length);
 const line=lines[0].line;
 const chain=/\$td<64\?(\$b\d+)\(\$v0,\$v1,\$v2,\$v3,\$v4,\$v5,\$td\+1\):run_named6\((\$b\d+),\$v0,\$v1,\$v2,\$v3,\$v4,\$v5,\$td\)/.exec(line);
 if(!chain)fail('metadata_write declaration does not expose the expected 6-argument call site');
 if(chain[1]!==chain[2])fail('metadata_write call-site function mismatch');
 const fn=chain[1];
 const signature='function '+fn+'($v0,$v1,$v2,$v3,$v4,$v5,$td=0){';
 const first=source.indexOf(signature);
 if(first<0)fail('Missing emitted metadata_write body '+fn);
 if(source.indexOf(signature,first+1)>=0)fail('Duplicate emitted signature '+signature);
 const offsetInsert=first+signature.length;
 const bodyEnd=source.indexOf('\nfunction ',first+1);
 const body=source.slice(offsetInsert,bodyEnd<0?source.length:bodyEnd);
 for(const marker of ['$p_u32_mul($v2,2)','$p_array_set($v1,$v2,$v5)','checker_arena.MetadataTables']){
  if(!body.includes(marker))fail('metadata_write body lacks '+marker);
 }
 return {canonical:suffix,emittedFunction:fn,insertionOffset:offsetInsert,bodyBytes:body.length};
}

function verifyBoolRepresentation(source){
 // The same runtime text also appears inside an emitter string literal; only a
 // top-level definition line is the active representation.
 const required=[
  {name:'$p_is_true',text:'const $p_is_true=(a)=>a===true;'},
  {name:'$p_is_false',text:'const $p_is_false=(a)=>a===false;'},
  {name:'$p_u32_is_eq',text:'const $p_u32_is_eq=(a,b)=>a===b;'},
 ];
 const observed=[];
 for(const {name,text} of required){
  const matches=[...source.matchAll(new RegExp('^'+text.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')+'$','gm'))];
  if(matches.length!==1)fail('Expected exactly one active boolean primitive '+name+', found '+matches.length);
  observed.push({name,text,offset:matches[0].index});
 }
 return {runtimeRepresentation:'JS primitive booleans: true/false compared with ===',primitives:observed};
}

function applyInsertions(original,insertions){
 let out=Buffer.from(original);
 const order=[...insertions].sort((a,b)=>b.offset-a.offset);
 for(const insertion of order){
  out=Buffer.concat([out.subarray(0,insertion.offset),Buffer.from(insertion.insertion,'utf8'),out.subarray(insertion.offset)]);
 }
 return out;
}

function reconstructOriginal(counted,insertions){
 // After removing every earlier insertion, the original prefix is restored, so
 // the current insertion sits exactly at its recorded original byte offset.
 let out=Buffer.from(counted);
 for(const insertion of [...insertions].sort((a,b)=>a.offset-b.offset)){
  const at=insertion.offset,text=Buffer.from(insertion.insertion,'utf8');
  if(!out.subarray(at,at+text.length).equals(text))fail('Counted image is not the declared insertion transform at '+insertion.id+' (offset '+insertion.offset+')');
  out=Buffer.concat([out.subarray(0,at),out.subarray(at+text.length)]);
 }
 return out;
}

function verifyFrozenInputs(request){
 for(const [path,digest] of Object.entries(request.pins)){
  if(realpathSync(path)!==path)fail('Pinned path is not canonical: '+path);
  if(hashPath(path)!==digest)fail('Pinned input drift: '+path);
 }
 for(const [path,digest] of Object.entries(request.inputs)){
  if(realpathSync(path)!==path)fail('Input path is not canonical: '+path);
  if(hashPath(path)!==digest)fail('Frozen source closure drift: '+path);
 }
 if(request.pins[FROZEN_ROOT]!==FROZEN_ROOT_SHA)fail('Frozen compiler root is not covered by the request pins');
 if(request.pins[FROZEN_CHECKER_ARENA]!==hashPath(FROZEN_CHECKER_ARENA))fail('Frozen checker_arena is not covered by the request pins');
}

function main(){
 // 1. Authority: freeze the accepted source checkpoint's checker_arena without
 // touching the working tree. MetadataCandidate may edit the working file.
 const authority=execFileSync('git',['-C',REPO,'show',AUTHORITY_COMMIT+':bend2/selfhost/checker_arena.bend'],{maxBuffer:64*1024*1024});
 const authoritySha=sha(authority);
 if(authoritySha!==REPO_CHECKER_ARENA_SHA)fail('git '+AUTHORITY_COMMIT+' checker_arena is not the accepted baseline: '+authoritySha);
 mkdirSync(AUTHORITY_DIR,{recursive:true});
 const authorityState=writeOnce(AUTHORITY_FILE,authority);
 const workingSha=hashPath(REPO_CHECKER_ARENA);

 // 2. Request and frozen source authority.
 requireHash(REQUEST,REQUEST_SHA);
 const request=JSON.parse(readFileSync(REQUEST,'utf8'));
 if(request.schemaVersion!==1)fail('Unexpected request schema');
 if(JSON.stringify(request.exports)!==JSON.stringify(['parsed_module','parse_with_fuel','expand_modules_start','template_step','check_expanded_start','inspect_checked_start','checker_step','emit_modules_start','emit_library_start','emitter_step','emit_c_modules_start','emit_c_library_start','c_emitter_step']))fail('Request exports differ from the frozen throughput ABI');
 if(request.node!==NODE)fail('Request node differs from the retained toolchain');
 if(request.root!==FROZEN_ROOT)fail('Request root differs from the authenticated frozen root');
 if(request.image!==ORIGINAL_IMAGE)fail('Request image differs from the accepted R12 image');
 if(request.expectedSelfhostOutput!==EXPECTED_OUTPUT_SHA)fail('Request expected output differs from the retained baseline');
 for(const [key,value] of Object.entries({memoryMiB:8192,rssMiB:8192,pollMs:10,timeoutMs:600000}))if(request.limits?.[key]!==value)fail('Request guard limit drift: '+key);
 if(hashPath(FROZEN_ROOT)!==FROZEN_ROOT_SHA)fail('Frozen compiler root drift');
 verifyFrozenInputs(request);

 // 3. Counted copy of the actual R12 compiler image.
 requireHash(ORIGINAL_IMAGE,ORIGINAL_SHA);
 const original=readFileSync(ORIGINAL_IMAGE);
 if(writeOnce(ORIGINAL_COPY,original)!=='reused'&&!readFileSync(ORIGINAL_COPY).equals(original))fail('Original image copy drift');
 const source=original.toString('utf8');
 if(!Buffer.from(source,'utf8').equals(original))fail('R12 image is not losslessly representable as UTF-8');
 const byteOffset=charIndex=>Buffer.byteLength(source.slice(0,charIndex),'utf8');
 const representation=verifyBoolRepresentation(source);
 const lines=declarationLines(source);
 const functions=POOLS.map(entry=>{
  const suffix='checker_arena.'+entry.pool+'_pool.room_select';
  const matches=lines.filter(row=>{
   const keyEnd=row.line.indexOf('"]=',5);
   return keyEnd>0&&row.line.slice(5,keyEnd).endsWith(suffix);
  });
  if(matches.length!==1)fail('Expected exactly one '+suffix+' declaration, found '+matches.length);
  const info=deriveRoomSelect(source,matches[0].line,matches[0].offset,entry);
  const insertion='if($v4===true){$g34.grow['+POOLS.indexOf(entry)+']++;}else if($v4===false){$g34.norm['+POOLS.indexOf(entry)+']++;}else{$g34.bad['+POOLS.indexOf(entry)+']++;}';
  return {id:info.emittedFunction,kind:'room_select',canonical:info.canonical,declarationKey:info.declarationKey,emittedFunction:info.emittedFunction,charOffset:info.insertionOffset,offset:byteOffset(info.insertionOffset),insertion,bodyBytes:info.bodyBytes};
 });
 const metadata=deriveMetadataWrite(source);
 functions.push({id:metadata.emittedFunction,kind:'metadata_write',canonical:metadata.canonical,declarationKey:'../bend2/selfhost/checker_arena.metadata_write',emittedFunction:metadata.emittedFunction,charOffset:metadata.insertionOffset,offset:byteOffset(metadata.insertionOffset),insertion:'if($v2>=0&&$v2<6){$g34.meta[$v2]++;if($v3===$v4){$g34.metaFull[$v2]++;}}else{$g34.metaBad++;}',bodyBytes:metadata.bodyBytes});
 const offsets=new Set(functions.map(row=>row.offset));
 if(offsets.size!==functions.length)fail('Insertion offsets are not unique');
 const emitted=new Set(functions.map(row=>row.emittedFunction));
 if(emitted.size!==functions.length)fail('Emitted function mapping is not injective');
 const insertions=[{id:'prelude',kind:'prelude',offset:0,insertion:PRELUDE},...functions];
 const counted=applyInsertions(original,insertions);
 if(!reconstructOriginal(counted,insertions).equals(original))fail('Declared transform does not reconstruct the original image');
 const countedState=writeOnce(COUNTED_COPY,counted);
 if(!readFileSync(COUNTED_COPY).equals(counted))fail('Counted image copy drift');

 const transform={
  schemaVersion:1,
  diagnosticOnly:true,
  timingAcceptance:false,
  target:'accepted R12 compiler image, ordinary-append/growth discrimination',
  original:{path:ORIGINAL_IMAGE,sha256:ORIGINAL_SHA,bytes:original.length},
  instrumented:{path:COUNTED_COPY,sha256:sha(counted),bytes:counted.length},
  reversible:{method:'Insertions recorded at original byte offsets; reconstruct by applying in descending offset order.',exactOriginalReconstruction:true},
  representation,
  canonicalOrder:POOLS.map(entry=>'checker_arena.'+entry.pool+'_pool.room_select'),
  insertions,
  metadataWrite:{canonical:metadata.canonical,emittedFunction:metadata.emittedFunction,slotArgument:'$v2',usedArgument:'$v3',capacityArgument:'$v4',counts:'meta[slot]',fullAtWrite:'metaFull[slot] when used===capacity'},
  limitations:[
   'word_pool.room_select growth entries include internal reserve_words growth steps (checker_arena.bend:1104-1118), not only ordinary appends.',
   'word_pool.room_select ordinary entries also include reserve_words reservation steps; word ordinary is therefore not a pure append count.',
   'reserve_words bypasses metadata_write (checker_arena.bend:1113), so word-slot metadata_write counters do not cover reservation steps.',
   'Counts are invocation counts through the emitted functions; they are not timings, allocations, or acceptance evidence.',
   'Instrumentation adds one branch and six counter increments per call; it does not change returned values or fuel.'
  ]
 };
 writeFileSync(TRANSFORM,JSON.stringify(transform,null,2)+'\n');

 // 4. Pin every executable input before and after a run.
 const pins={
  schemaVersion:1,
  diagnosticOnly:true,
  directory:DIR,
  request:{path:REQUEST,sha256:REQUEST_SHA},
  root:{path:FROZEN_ROOT,sha256:FROZEN_ROOT_SHA},
  expectedOutputSha256:EXPECTED_OUTPUT_SHA,
  tools:{node:{path:NODE,sha256:hashPath(NODE),version:execFileSync(NODE,['--version'],{encoding:'utf8'}).trim()},bun:{path:BUN,sha256:existsSync(BUN)?hashPath(BUN):null}},
  authority:{
   commit:AUTHORITY_COMMIT,
   command:'git -C '+REPO+' show '+AUTHORITY_COMMIT+':bend2/selfhost/checker_arena.bend',
   acceptedBaselineSha256:REPO_CHECKER_ARENA_SHA,
   frozenCopy:{path:AUTHORITY_FILE,sha256:authoritySha,state:authorityState},
   frozenRootCheckerArena:{path:FROZEN_CHECKER_ARENA,sha256:hashPath(FROZEN_CHECKER_ARENA)},
