 if(counted.length!==transform.instrumented.bytes)throw Error('Counted image byte count mismatch');
 if(!Array.isArray(transform.insertions)||transform.insertions.length!==8)throw Error('Expected prelude + six room_select + metadata_write insertions');
 // Independent reconstruction from declared offsets only; removing earlier
